<?php
require_once __DIR__.'/../includes/bootstrap.php';require_admin();$statuses=['Pending','Confirmed','Processing','Ready for Pickup','Completed','Cancelled'];$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$status=$_POST['status']??'';if(in_array($status,$statuses,true)){$st=$pdo->prepare("UPDATE orders SET status=? WHERE id=?");$st->execute([$status,$id]);flash('Order status updated.');redirect('/lakshmi-electricals/admin/orders.php');}else $error='Invalid status.';}
$orders=$pdo->query("SELECT o.*,u.name,u.email FROM orders o JOIN users u ON u.id=o.user_id ORDER BY o.created_at DESC")->fetchAll();
$pageTitle='Manage order requests';require __DIR__.'/../includes/header.php';?>
<div class="admin-layout"><aside class="admin-sidebar"><span class="eyebrow">MANAGEMENT</span><h2>Admin panel</h2><a href="/lakshmi-electricals/admin/dashboard.php">Dashboard</a><a href="/lakshmi-electricals/admin/categories.php">Categories</a><a href="/lakshmi-electricals/admin/products.php">Products</a><a class="active" href="/lakshmi-electricals/admin/orders.php">Order requests</a><a href="/lakshmi-electricals/admin/users.php">Customers</a></aside><section class="admin-content"><div class="section-heading"><div><span class="eyebrow">CUSTOMER REQUESTS</span><h1>Order requests</h1></div></div><?php if($error): ?><div class="alert error"><?= e($error) ?></div><?php endif; ?><?php if(!$orders): ?><div class="empty-state"><h3>No order requests yet</h3></div><?php else: ?><div class="orders-list"><?php foreach($orders as $o): ?><article class="order-card"><div class="order-top"><div><small>REQUEST #<?= (int)$o['id'] ?> · <?= e(date('d M Y, h:i A',strtotime($o['created_at']))) ?></small><h2><?= e($o['name']) ?></h2><p><?= e($o['email']) ?><?= $o['contact_phone']?' · '.e($o['contact_phone']):'' ?></p></div><strong class="price"><?= money($o['total_amount']) ?></strong></div><p>Fulfilment: <?= e(ucfirst($o['fulfilment'])) ?><?= $o['notes']?' · Notes: '.e($o['notes']):'' ?></p><details><summary>Requested items</summary><?php $st=$pdo->prepare("SELECT * FROM order_items WHERE order_id=?");$st->execute([$o['id']]);foreach($st as $it): ?><p><?= e($it['product_name']) ?> — <?= (int)$it['quantity'] ?> × <?= money($it['unit_price']) ?> = <?= money($it['subtotal']) ?></p><?php endforeach; ?></details><form method="post" class="inline-form"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$o['id'] ?>"><label>Status<select name="status"><?php foreach($statuses as $s): ?><option <?= $s===$o['status']?'selected':'' ?>><?= e($s) ?></option><?php endforeach; ?></select></label><button class="btn btn-gold">Update status</button></form></article><?php endforeach; ?></div><?php endif; ?></section></div>
